<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://minnesotainsuranceappraiser.com/#business","name":"Minnesota Insurance Appraiser","url":"https://minnesotainsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@minnesotainsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://minnesotainsuranceappraiser.com/#logo","url":"https://minnesotainsuranceappraiser.com/web-app-manifest-512x512.png","contentUrl":"https://minnesotainsuranceappraiser.com/web-app-manifest-512x512.png","width":512,"height":512,"caption":"Minnesota Insurance Appraiser"},"image":{"@id":"https://minnesotainsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"MN","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@minnesotainsuranceappraiser.com","contactType":"customer service","areaServed":"US-MN","availableLanguage":"en"}],"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across Minnesota’s 87 counties.","areaServed":[{"@type":"State","name":"Minnesota"},{"@type":"City","name":"Minneapolis","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"St. Paul","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Rochester","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Duluth","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Bloomington","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Plymouth","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Woodbury","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Eagan","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Blaine","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"St. Cloud","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Mankato","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Moorhead","containedInPlace":{"@type":"State","name":"Minnesota"}}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/appraisal-clause-help/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Townhome & HOA Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/hail-roof-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado, Derecho & Straight-Line Wind","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/tornado-derecho-wind-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Burst-Pipe Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam, Snow Load & Frozen Pipe Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/ice-dam-winter-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/appraisal-umpire/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/contents-personal-property-appraisal/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hail damage","Ice dams","Derecho and tornado wind damage","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://minnesotainsuranceappraiser.com/#website","url":"https://minnesotainsuranceappraiser.com/","name":"Minnesota Insurance Appraiser","publisher":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://minnesotainsuranceappraiser.com/common-questions/#webpage","url":"https://minnesotainsuranceappraiser.com/common-questions/","name":"Insurance Appraisal Questions | Minnesota Owners’ FAQ","description":"Answers to common Minnesota insurance appraisal questions, grouped by topic: basics, costs and fees, timing, state rules and working with us.","inLanguage":"en-US","isPartOf":{"@id":"https://minnesotainsuranceappraiser.com/#website"},"about":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"publisher":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://minnesotainsuranceappraiser.com/common-questions/#primaryimage","url":"https://minnesotainsuranceappraiser.com/assets/img/photos/living-room.webp","width":1024,"height":683},"breadcrumb":{"@id":"https://minnesotainsuranceappraiser.com/common-questions/#breadcrumb"},"mainEntity":{"@id":"https://minnesotainsuranceappraiser.com/common-questions/#faqpage"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://minnesotainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Common questions","item":"https://minnesotainsuranceappraiser.com/common-questions/"}],"@id":"https://minnesotainsuranceappraiser.com/common-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What does an insurance appraiser actually do?","acceptedAnswer":{"@type":"Answer","text":"An insurance appraiser values the cost to repair or replace damaged property under the terms of a policy, then negotiates that amount with the other side’s appraiser. The goal is a signed award that sets the amount of loss."}},{"@type":"Question","name":"How is appraisal different from going to court?","acceptedAnswer":{"@type":"Answer","text":"Appraisal is a narrower, policy-based process that decides only the dollar amount of a covered loss. Lawsuits handle coverage, contract and bad-faith questions, and they usually take longer and cost more."}},{"@type":"Question","name":"Can the insurance company demand appraisal too?","acceptedAnswer":{"@type":"Answer","text":"Yes. The provision usually lets either party make a written demand. If the insurer invokes it, you still choose your own appraiser."}},{"@type":"Question","name":"Is the appraisal award final?","acceptedAnswer":{"@type":"Answer","text":"On the amount of loss, an award signed by two of the three panel members is generally binding. Courts can set awards aside only in narrow situations, such as fraud or a panel exceeding its authority."}},{"@type":"Question","name":"Does appraisal work for commercial buildings?","acceptedAnswer":{"@type":"Answer","text":"Yes. Most commercial property forms contain an appraisal provision, and the process for apartment buildings, churches, retail and industrial properties follows the same basic steps."}},{"@type":"Question","name":"Who pays for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Each side usually pays its own appraiser, and the umpire’s fee is commonly split equally. Check your policy, because some forms allocate costs differently."}},{"@type":"Question","name":"How do appraisers charge?","acceptedAnswer":{"@type":"Answer","text":"Arrangements vary: hourly, flat fee, or a combination. Because appraisers must be disinterested, many avoid contingency fees tied to the size of the award. Get the fee agreement in writing before you sign anything."}},{"@type":"Question","name":"Is appraisal worth it for a small gap?","acceptedAnswer":{"@type":"Answer","text":"Often not. If the difference is only a few thousand dollars, appraisal fees can eat most of it, and a well-supported supplement request may be the better route. Our claim gap fee estimator can help you run illustrative numbers."}},{"@type":"Question","name":"Are there costs besides the appraiser and umpire?","acceptedAnswer":{"@type":"Answer","text":"Sometimes. Specialized input such as an engineer’s report, a contractor’s detailed bid or a matching test for siding may add cost, depending on the dispute."}},{"@type":"Question","name":"How long does appraisal take in Minnesota?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals finish within two to four months, but timing depends on the size of the loss, scheduling, winter access to roofs and how many items reach the umpire."}},{"@type":"Question","name":"How quickly must I name my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies allow about 20 days after the written demand. Read your own appraisal paragraph, because the window can differ."}},{"@type":"Question","name":"Does appraisal stop the lawsuit deadline?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Standard policy language commonly limits suits to two years after the loss, and appraisal may not pause that period. Confirm the deadline in your policy and with an attorney."}},{"@type":"Question","name":"Can appraisal happen in winter?","acceptedAnswer":{"@type":"Answer","text":"Yes, though roof inspections may wait for safe conditions. Interior damage from ice dams can usually be inspected and priced right away."}},{"@type":"Question","name":"When is recoverable depreciation paid after an award?","acceptedAnswer":{"@type":"Answer","text":"Many policies pay actual cash value first and release recoverable depreciation once repairs are completed and documented. Your policy sets the deadline for completing repairs and claiming it."}},{"@type":"Question","name":"Where does Minnesota’s appraisal provision come from?","acceptedAnswer":{"@type":"Answer","text":"Minnesota’s standard fire policy statute, Minn. Stat. § 65A.01, includes an appraisal provision with two competent and disinterested appraisers, an umpire, and an award by any two. Most policies sold here follow that structure."}},{"@type":"Question","name":"Can appraisers decide what caused the damage in Minnesota?","acceptedAnswer":{"@type":"Answer","text":"In Quade v. Secura Insurance (2012), the Minnesota Supreme Court indicated that appraisers may decide causation as part of the amount of loss. Coverage questions still belong to the courts."}},{"@type":"Question","name":"Who regulates insurers in Minnesota?","acceptedAnswer":{"@type":"Answer","text":"The Minnesota Department of Commerce oversees insurance companies and licenses agents, adjusters and public adjusters. It also accepts consumer complaints."}},{"@type":"Question","name":"What if I can’t get coverage from a regular insurer?","acceptedAnswer":{"@type":"Answer","text":"The Minnesota FAIR Plan provides basic property coverage when the voluntary market won’t. Minnesota has no separate state wind pool, so wind and hail are typically covered in the regular policy."}},{"@type":"Question","name":"Who appoints an umpire if the appraisers can’t agree?","acceptedAnswer":{"@type":"Answer","text":"Either party can ask a court to appoint one, typically the district court in the county where the property is located."}},{"@type":"Question","name":"Are you lawyers or public adjusters?","acceptedAnswer":{"@type":"Answer","text":"No. We are independent appraisers. We value the amount of loss and serve as appraisers or umpires; we don’t give legal advice or negotiate coverage."}},{"@type":"Question","name":"What should I send for a first review?","acceptedAnswer":{"@type":"Answer","text":"Your full policy, the carrier’s estimate, any contractor bids, photos and key correspondence. That is usually enough to tell whether appraisal makes sense."}},{"@type":"Question","name":"Do you work outside the Twin Cities?","acceptedAnswer":{"@type":"Answer","text":"Yes. We handle claims throughout Minnesota, from the metro to Duluth, Rochester, St. Cloud, Mankato and smaller communities."}},{"@type":"Question","name":"Can you serve as an umpire?","acceptedAnswer":{"@type":"Answer","text":"Yes, when both parties or a court select us and we have no conflict with either side. Umpire work is strictly neutral."}},{"@type":"Question","name":"How do I get started?","acceptedAnswer":{"@type":"Answer","text":"Use the contact form or call. We’ll ask a few questions about the claim, review your documents and tell you plainly whether appraisal looks like the right tool."}}],"@id":"https://minnesotainsuranceappraiser.com/common-questions/#faqpage"}]}</script>
</head>
